function validate([n, roads]) {
  if (!Number.isInteger(n) || n < 1 || n > 200) return 'n must be between 1 and 200.';
  if (!Array.isArray(roads) || roads.length < n - 1 || roads.length > n * (n - 1) / 2) return 'roads needs between n - 1 and n * (n - 1) / 2 roads.';
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
  const seen = new Set();
  let groups = n;
  for (const road of roads) {
    if (!Array.isArray(road) || road.length !== 3) return 'Each road is [u, v, time].';
    const [u, v, time] = road;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || v < 0 || u >= n || v >= n) return 'Road ends must be intersections 0 to n - 1.';
    if (u === v) return 'A road must join two different intersections.';
    if (!Number.isInteger(time) || time < 1 || time > 1000000000) return 'Each time is between 1 and 10^9.';
    const key = Math.min(u, v) * 1000 + Math.max(u, v);
    if (seen.has(key)) return 'At most one road may join two intersections.';
    seen.add(key);
    const a = find(u);
    const b = find(v);
    if (a !== b) { parent[a] = b; groups--; }
  }
  if (groups !== 1) return 'Every intersection must be reachable from every other.';
  return null;
}

