function countPaths(n, roads) {
  // Bellman-Ford for the times, then count routes over the roads that lie on some fastest route.
  const dist = new Array(n).fill(Infinity);
  dist[0] = 0;
  for (let pass = 0; pass < n; pass++) {
    for (const [u, v, t] of roads) {
      if (dist[u] + t < dist[v]) dist[v] = dist[u] + t;
      if (dist[v] + t < dist[u]) dist[u] = dist[v] + t;
    }
  }
  const memo = new Map();
  const count = (x) => {
    if (x === 0) return 1;
    if (memo.has(x)) return memo.get(x);
    let total = 0;
    for (const [u, v, t] of roads) {
      if (v === x && dist[u] + t === dist[x]) total = (total + count(u)) % 1000000007;
      if (u === x && dist[v] + t === dist[x]) total = (total + count(v)) % 1000000007;
    }
    memo.set(x, total);
    return total;
  };
  return count(n - 1);
}

