function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(150, 200) : int(1, 8);
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = int(0, i);
    [order[i], order[j]] = [order[j], order[i]];
  }
  const roads = [];
  const used = new Set();
  const add = (u, v, time) => {
    const key = Math.min(u, v) * 1000 + Math.max(u, v);
    if (u === v || used.has(key)) return;
    used.add(key);
    roads.push(rand() < 0.5 ? [u, v, time] : [v, u, time]);
  };
  if (large && rand() < 0.4) {
    // Layers of equal-length roads create a huge number of shortest routes.
    const width = int(2, 4);
    const middle = order.filter(x => x !== 0 && x !== n - 1);
    const layers = [[0]];
    for (let i = 0; i < middle.length; i += width) layers.push(middle.slice(i, i + width));
    layers.push([n - 1]);
    for (let k = 0; k + 1 < layers.length; k++) {
      for (const u of layers[k]) for (const v of layers[k + 1]) add(u, v, 1);
    }
    for (let extra = 0; extra < 300; extra++) add(int(0, n - 1), int(0, n - 1), int(500000000, 1000000000));
    return [n, roads];
  }
  const maxTime = [2, 3, 10, 1000000000][int(0, 3)];
  for (let i = 1; i < n; i++) add(order[i], order[int(0, i - 1)], int(1, maxTime));
  const pairs = n * (n - 1) / 2;
  const extraCount = large ? int(n, 2500) : int(0, pairs);
  for (let extra = 0; extra < extraCount; extra++) add(int(0, n - 1), int(0, n - 1), int(1, maxTime));
  return [n, roads];
}
